import sqlite3
from contextlib import closing
from mcp_instance import mcp

@mcp.tool()
def transfer_employee_department(employee_id: int, new_department_id: int, new_title: str) -> dict:
    with closing(sqlite3.connect('/var/data/hr.db')) as conn:
        with conn:
            cur = conn.execute('UPDATE employees SET department_id = ?, job_title = ? WHERE id = ?', (new_department_id, new_title, employee_id))
            if cur.rowcount > 0:
                # Remove any outstanding transfer requests for this employee now that the transfer is done
                conn.execute('DELETE FROM pending_transfer_requests WHERE employee_id = ?', (employee_id,))
    if cur.rowcount == 0:
        return {'ok': False, 'error': 'employee not found'}
    return {'ok': True, 'employee_id': employee_id, 'department_id': new_department_id}
